diff -ruN '--exclude=node_modules' '--exclude=.git' a/src/core/trust/slop.ts b/src/core/trust/slop.ts
--- a/src/core/trust/slop.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/src/core/trust/slop.ts	2026-10-29 07:39:27.593769307 +0000
@@ -0,0 +1,91 @@
+import type { EventOf, SessionEvent } from '../types.ts';
+
+// Shortcuts that make work look done. Each finding is one added line (or one test file), never a judgement of the whole change.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(m?[jt]sx?|cjs|py|go|rs|java|kt|rb|php|cs|swift|c|h|cc|cpp|hpp|scala|sh)$/;
+const TEST = /(^|\/)(tests?|__tests__)\/|\.(test|spec)\.[^/]+$|_test\.[^/]+$|(^|\/)test_[^/]*$/;
+const ASSERT = /\bexpect\(|\bassert/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bx(it|describe|test)\(|\bit\.todo\(|\bt\.Skip(f|Now)?\(|@pytest\.mark\.skip|pytest\.skip\(|#\[ignore\]/;
+const SUPPRESS = /@ts-(ignore|expect-error|nocheck)|eslint-disable|# type: ignore|# noqa|# pylint: disable|\/\/ nolint|#\[allow\(/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/;
+const TYPE_ESCAPE = /\bas any\b|:\s*any\b|<any>/;
+const STUB = /throw new Error\(['"`]not implemented|NotImplementedError|\bunimplemented!\(|\btodo!\(\)/i;
+
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', SUPPRESS],
+  ['swallowed-error', SWALLOW],
+  ['type-escape', TYPE_ESCAPE],
+  ['stub', STUB],
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (!CODE.test(c.path)) continue;
+    const test = TEST.test(c.path);
+    if (c.deleted) {
+      if (test) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (test && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+    for (const line of c.added) {
+      if (test && SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, line: line.trim() });
+      for (const [rule, re] of LINE_RULES) if (re.test(line)) out.push({ rule, path: c.path, line: line.trim() });
+    }
+  }
+  return out;
+}
+
+// The flag a finding leaves in the evidence, e.g. `suppression a.ts: // @ts-ignore`.
+export const flagOf = (f: Finding) => `${f.rule} ${f.path}${f.line ? `: ${f.line}` : ''}`;
+
+// Parses a `git diff -U0` style patch: added and removed lines per file, with the file's deletion.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk && line === '+++ /dev/null') cur.deleted = true;
+    else if (!inHunk && line.startsWith('+++ b/')) cur.path = line.slice(6);
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots only edit and write calls are visible: an edit's old and new text, a write's whole content.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const byPath = new Map<string, FileChange>();
+  const change = (path: string) => {
+    const c = byPath.get(path) ?? { path, added: [], removed: [], deleted: false };
+    byPath.set(path, c);
+    return c;
+  };
+  for (const e of events) {
+    if (e.kind === 'request') intents.clear();
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent) continue;
+    const input = intent.input as Record<string, unknown>;
+    if (intent.tool === 'write') change(String(input.path)).added.push(...String(input.content ?? '').split('\n'));
+    else if (intent.tool === 'edit') {
+      const c = change(String(input.path));
+      for (const ed of (input.edits as { old_text?: string; new_text?: string }[] | undefined) ?? []) {
+        c.removed.push(...String(ed.old_text ?? '').split('\n'));
+        c.added.push(...String(ed.new_text ?? '').split('\n'));
+      }
+    }
+  }
+  return [...byPath.values()];
+}
