+// Slop: shortcuts that make work look done. It reads the run's own added and removed lines, not the whole
+// tree, and only flags; the done gate never refuses on it.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(c|cc|cpp|h|hpp|cs|go|java|js|jsx|mjs|cjs|ts|tsx|kt|py|rb|rs|swift|php|sh)$/;
+const TEST = /(\.test\.|\.spec\.|_test\.|(^|\/)test_[^/]*$|(^|\/)tests?\/)/;
+const ASSERT = /\b(expect|assert\w*)\b/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bx(it|describe|test)\(|\.Skip\w*\(|mark\.skip/;
+
+// Line rules run on added lines only. `testOnly` rules apply to test files.
+const LINE_RULES: [rule: string, re: RegExp, testOnly: boolean][] = [
+  ['test-skipped', SKIP, true],
+  ['suppression', /@ts-(ignore|expect-error|nocheck)|eslint-disable|# ?type: ?ignore|# ?noqa|# ?pylint: ?disable|\/\/ ?nolint/, false],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/, false],
+  ['type-escape', /\bas any\b|:\s*any\b/, false],
+  ['stub', /not implemented|NotImplementedError|\btodo!\(|\bunimplemented!\(/i, false],
+];
+
+const count = (lines: string[], re: RegExp) => lines.filter((l) => re.test(l)).length;
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  return changes.flatMap((c) => {
+    if (!CODE.test(c.path)) return [];
+    const test = TEST.test(c.path);
+    if (test && c.deleted) return [{ rule: 'test-deleted', path: c.path }];
+    const out: SlopFinding[] = [];
+    if (test && count(c.removed, ASSERT) > count(c.added, ASSERT)) out.push({ rule: 'test-weakened', path: c.path });
+    for (const [rule, re, testOnly] of LINE_RULES) {
+      if (testOnly && !test) continue;
+      for (const l of c.added) if (re.test(l)) out.push({ rule, path: c.path, line: l.trim() });
+    }
+    return out;
+  });
+}
+
+// One flag per finding, as the reminder and the receipt show it.
+export const slopFlags = (changes: FileChange[]) =>
+  [...new Set(findSlop(changes).map((f) => `${f.rule} ${f.path}${f.line ? `: ${f.line}` : ''}`))];
+
+export const slopReminder = (flags: string[]) =>
+  `cedia found shortcuts in this run's changes that make the work look done:\n${flags.map((f) => `- ${f}`).join('\n')}\nIf one is a shortcut, fix it: restore the test, handle the error, implement the stub. If one is needed, say why in your report.`;
+
+// Parses a `git diff-tree -p -U0` patch.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[2]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// The change one edit or write call makes, when there are no snapshots to diff. A write has no old text to compare.
+export function changeFromCall(tool: string, input: Record<string, unknown>): FileChange[] {
+  const path = String(input.path);
+  if (tool === 'write') return [{ path, added: String(input.content).split('\n'), removed: [], deleted: false }];
+  if (tool !== 'edit' || !Array.isArray(input.edits)) return [];
+  const edits = input.edits as { old_text: string; new_text: string }[];
+  return [{ path, added: edits.flatMap((e) => e.new_text.split('\n')), removed: edits.flatMap((e) => e.old_text.split('\n')), deleted: false }];
+}
