diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/pricing-rules.test.ts b/test/pricing-rules.test.ts
--- a/test/pricing-rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/pricing-rules.test.ts	2026-10-29 07:36:08.972660066 +0000
@@ -0,0 +1,35 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('bulk tiers start at 10 units (5%) and 50 units (10%)', () => {
+    // 9 mugs = 4050, no discount
+    expect(totals(cart('US', [['MUG', 9]])).lines[0].discount).toBe(0);
+    // 10 mugs = 4500; 5% = 225
+    expect(totals(cart('US', [['MUG', 10]])).lines[0].discount).toBe(225);
+    // 50 mugs = 22500; 10% = 2250
+    expect(totals(cart('US', [['MUG', 50]])).lines[0].discount).toBe(2250);
+  });
+
+  test('lines of the same sku are merged before the bulk tier is chosen', () => {
+    // 5 + 5 mugs = 10 units, so the 5% tier applies to the merged line
+    const t = totals(cart('US', [['MUG', 5], ['MUG', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]).toMatchObject({ quantity: 10, subtotal: 4500, discount: 225 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2 bags = 4400 >= 4000; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ shipping: 0, tax: 880, total: 5280 });
+    // 4 mugs + 1 bag = 4000 exactly; tax 800
+    expect(totals(cart('UK', [['MUG', 4], ['BAG', 1]]))).toMatchObject({ subtotal: 4000, shipping: 0, tax: 800, total: 4800 });
+  });
+
+  test('the free-shipping threshold uses the discounted subtotal, after the coupon', () => {
+    // 2 bags = 4400; FLAT5 takes 500 off -> 3900, below 4000, so shipping 700 applies
+    // tax 20% of (3900 + 700) = 920
+    expect(totals(cart('UK', [['BAG', 2]], 'FLAT5'))).toMatchObject({ coupon: 500, shipping: 700, tax: 920, total: 5520 });
+  });
+});

