@@ -11,10 +11,31 @@
 //   keeps exactly max ("ab-cd-ef" with max 5 is "ab-cd").
 //
 // uniqueSlug(slug, taken): slug itself if it is not in taken, else slug-2, slug-3, ... the first free one.
+const SPECIAL: Record<string, string> = {
+  ß: 'ss',
+  æ: 'ae',
+  œ: 'oe',
+  ø: 'o',
+  ł: 'l',
+  đ: 'd',
+};
+
 export function slugify(text: string, max?: number): string {
-  throw new Error('not implemented');
+  const slug = text
+    .toLowerCase()
+    .replace(/[ßæœøłđ]/g, (c) => SPECIAL[c])
+    .normalize('NFD')
+    .replace(/\p{M}/gu, '')
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-|-$/g, '');
+  if (max === undefined || slug.length <= max) return slug;
+  const cut = slug.lastIndexOf('-', max);
+  return cut > 0 ? slug.slice(0, cut) : slug.slice(0, max);
 }

 export function uniqueSlug(slug: string, taken: Set<string>): string {
-  throw new Error('not implemented');
+  if (!taken.has(slug)) return slug;
+  let n = 2;
+  while (taken.has(`${slug}-${n}`)) n++;
+  return `${slug}-${n}`;
 }
diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/rules.test.ts b/test/rules.test.ts
--- a/test/rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/rules.test.ts	2026-10-29 07:37:23.536664498 +0000
@@ -0,0 +1,80 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+import { LRU } from '../src/lru.ts';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+
+test('parseDuration rules', () => {
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(187_200_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1h 30m')).toBe(5_400_000);
+  expect(parseDuration('  1h30m  ')).toBe(5_400_000);
+  expect(parseDuration('1.0004s')).toBe(1000);
+  expect(parseDuration('0.0015s')).toBe(2);
+  for (const bad of ['', '10', '5x', 'h', '-1s', '1 h', '1h-30m']) {
+    expect(() => parseDuration(bad)).toThrow(bad === '' ? 'invalid' : `"${bad}"`);
+  }
+});
+
+test('formatDuration rules', () => {
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(90_000)).toBe('1m30s');
+  expect(formatDuration(86_400_000)).toBe('1d');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(() => formatDuration(-1)).toThrow();
+});
+
+test('slugify rules', () => {
+  expect(slugify('Straße Æther Œuvre Øl Łódź Đ')).toBe('strasse-aether-oeuvre-ol-lodz-d');
+  expect(slugify('  --Hello!!  World--  ')).toBe('hello-world');
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('abcdefgh', 5)).toBe('abcde');
+  expect(slugify('ab cdefgh', 5)).toBe('ab');
+  expect(slugify('abcde-fgh', 5)).toBe('abcde');
+});
+
+test('uniqueSlug rules', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+});
+
+test('LRU rules', () => {
+  let t = 0;
+  const events: string[] = [];
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.onEvict = (k, v, r) => events.push(`${k}${v}:${r}`);
+  cache.set('a', 1);
+  t = 500;
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  expect(cache.keys()).toEqual(['a', 'b']);
+  cache.set('c', 3);
+  expect(events).toEqual(['b2:capacity']);
+  expect(cache.delete('a')).toBe(true);
+  expect(cache.delete('a')).toBe(false);
+  expect(events).toEqual(['b2:capacity', 'a1:delete']);
+
+  // expired entries are removed before a live one is evicted
+  t = 1400;
+  cache.set('d', 4);
+  expect(events.length).toBe(2);
+  t = 1500;
+  cache.set('e', 5);
+  expect(events.slice(2)).toEqual(['c3:expired']);
+  expect(cache.size).toBe(2);
+  expect(cache.keys()).toEqual(['e', 'd']);
+  t = 2400;
+  expect(cache.delete('d')).toBe(false);
+  expect(events.at(-1)).toBe('d4:expired');
+});
+
+test('LRU set refreshes the ttl', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(5, 1000, () => t);
+  cache.set('a', 1);
+  t = 999;
+  cache.set('a', 2);
+  t = 1500;
+  expect(cache.get('a')).toBe(2);
+});
